        "encounter_id": {
          "type": "integer",
          "description": "ID of the encounter to which the SOAP note belongs",
          "title": "Encounter Id"
        },
        "subjective": {
          "type": "string",
          "title": "Subjective"
        },
        "objective": {
          "type": "string",
          "title": "Objective"
